def test_managed_soperator_upgrade_continues_typed_checkpoint_under_same_locks(
    monkeypatch: pytest.MonkeyPatch,
    tmp_path: Path,
) -> None:
    events: list[str] = []
    attempts = 0

    @contextmanager
    def execution_lock(path: Path) -> Iterator[None]:
        events.append(f"enter:{path.name}")
        try:
            yield
        finally:
            events.append(f"exit:{path.name}")

    def run_locked(**_kwargs: object) -> None:
        nonlocal attempts
        attempts += 1
        events.append(f"run:{attempts}")
        if attempts == 1:
            raise soperator_migration_module.SoperatorMigrationCheckpointContinuation(
                "final target values accepted",
                boundary="final-target-values-accepted",
                progress_evidence={"status": "accepted", "revision": 7},
                retry_interval_seconds=0,
            )

    checkpoint_path = tmp_path / "checkpoint.json"
    monkeypatch.setattr(cli_module, "SoperatorMigrationExecutionLock", execution_lock)
    monkeypatch.setattr(
        cli_module,
        "_soperator_upgrade_checkpoint_path",
        lambda *_args, **_kwargs: checkpoint_path,
    )
    monkeypatch.setattr(
        cli_module,
        "_run_managed_soperator_cluster_upgrade_locked",
        run_locked,
    )

    cli_module._run_managed_soperator_cluster_upgrade(  # noqa: SLF001
        config_path=tmp_path / "config.yaml",
        source_payload={},
        target=cli_module._HelmChartUpgradeTarget(  # noqa: SLF001
            selector="apps:soperator@cluster",
            chart_id="soperator",
            target_ref="cluster",
        ),
        to_chart_version="1.0.0",
        to_k8s_version=None,
        to_os=None,
        to_gpu_stack_preset=None,
        node_group="",
        disruption_policy="safe-surge",
        drain_timeout="30m",
        strategy_max_surge_count=None,
        zero_surge_max_unavailable="all",
        max_parallel_worker_groups=1,
        backup_dir=None,
        populate_jail_refresh="auto",
        jail_persistent_mounts=(),
        jail_sfs_resize_policy="reject",
        jail_sfs_resize_to_gib=None,
        job_policy="fail",
        cancel_job=(),
        requeue_job=(),
        job_wait_timeout="0s",
        job_refresh_interval="30s",
        slurm_scheduling_pause=True,
        login_session_policy="target-ready",
        login_session_drain_timeout="0s",
        dry_run=False,
        interactive=False,
    )

    assert attempts == 2
    assert events == [
        "enter:config.lock",
        "enter:execute.lock",
        "run:1",
        "run:2",
        "exit:execute.lock",
        "exit:config.lock",
    ]


def test_external_soperator_discovery_refresh_defers_during_jail_mutation_boundary() -> None:
    checkpoint = {
        "completed_phases": ["discovery-and-plan"],
        "phase_state": {
            "populate-jail-refresh": {
                "consumer_switch_applied_at": "2026-07-20T00:00:00Z",
            }
        },
    }

    assert cli_module._external_soperator_discovery_refresh_deferred(checkpoint)  # noqa: SLF001
    assert not cli_module._external_soperator_discovery_refresh_deferred(None)  # noqa: SLF001


def test_external_soperator_discovery_refresh_defers_during_target_controller_gate() -> None:
    checkpoint = {
        "completed_phases": [
            "discovery-and-plan",
            "populate-jail-refresh",
        ],
        "controller_bridge": {
            "stage": "target-ha-active",
        },
        "phase_state": {
            "rolling-compute-migration": {
                "in_place_target_controller_command_gate": {
                    "status": "verified",
                },
                "in_place_target_native_controller_ha": {},
            }
        },
    }

    assert cli_module._external_soperator_discovery_refresh_deferred(checkpoint)  # noqa: SLF001

    checkpoint["phase_state"]["rolling-compute-migration"][
        "in_place_target_native_controller_ha"
    ] = {
        "cleanup_status": "controller-gate-removed",
        "controller_gate_removed_at": "2026-07-22T13:00:00Z",
    }
    assert not cli_module._external_soperator_discovery_refresh_deferred(checkpoint)  # noqa: SLF001


def test_locked_segment_projection_retains_accepted_migration_profile() -> None:
    source_report = {
        "report": {
            "migration_profile_id": "v4-to-target",
            "source_version": "4.0.2",
            "target_version": "4.0.2-ps.4",
        }
    }
    upgrade_path = {
        "migration_profile": {
            "id": "legacy-v1-to-target",
            "execution_contract": {
                "source_controller_pause": {
                    "required_before_target_compute_reconcile": True,
                }
            },
        },
        "soperator_chart": {
            "current_version": "1.22.3",
            "target_version": _soperator_test_chart_version(),
        },
    }
    segment = {
        "id": "segment-1",
        "current_k8s_version": "1.31",
        "target_k8s_version": "1.32",
        "soperator_app": {
            "current_version": "1.22.3",
            "target_version": _soperator_test_app_version(),
        },
        "soperator_chart": {
            "current_version": "1.22.3",
            "target_version": _soperator_test_chart_version(),
        },
    }

    projected = cli_module._source_report_for_locked_upgrade_segment(  # noqa: SLF001
        source_report=source_report,
        upgrade_path=upgrade_path,
        segment=segment,
    )

    assert projected["report"]["migration_profile_id"] == "legacy-v1-to-target"
    assert projected["report"]["source_version"] == "1.22.3"
    assert source_report["report"]["migration_profile_id"] == "v4-to-target"


