def _install_real_cluster_lease_constructor_probe(
    monkeypatch: pytest.MonkeyPatch,
    observed: dict[str, str],
) -> None:
    class _ConstructorCheckedClusterLease:
        def __init__(
            self,
            *,
            kube_context: str,
            cluster_id: str,
            campaign_fingerprint: str,
        ) -> None:
            real_lease = soperator_migration_module.SoperatorMigrationClusterLease(
                kube_context=kube_context,
                cluster_id=cluster_id,
                campaign_fingerprint=campaign_fingerprint,
            )
            observed["kube_context"] = real_lease.kube_context
            observed["cluster_id"] = real_lease.cluster_id
            observed["campaign_fingerprint"] = real_lease.campaign_fingerprint
            observed["kubeconfig"] = os.environ.get("KUBECONFIG", "")
            assert observed["kubeconfig"]
            assert Path(observed["kubeconfig"]).is_file()

        def __enter__(self) -> _ConstructorCheckedClusterLease:
            return self

        def assert_held(self) -> None:
            return None

        def __exit__(self, *_args: object) -> None:
            return None

    monkeypatch.setattr(
        cli_module, "SoperatorMigrationClusterLease", _ConstructorCheckedClusterLease
    )


def test_apply_post_flux_manifest_skips_helm_oci_status_output(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    configmap = {
        "apiVersion": "v1",
        "kind": "ConfigMap",
        "metadata": {"name": "rendered-soperator", "namespace": "soperator"},
    }
    manifest_path = tmp_path / "post-flux-helmrender-slurm-soperator.yaml"
    manifest_path.write_text(
        yaml.safe_dump_all(
            [
                {
                    "Pulled": "oci://example.invalid/charts/soperator:4.0.1-ps.2",
                    "Digest": "sha256:deadbeef",
                },
                configmap,
            ],
            explicit_start=True,
            sort_keys=False,
        ),
        encoding="utf-8",
    )
    applied_docs: list[list[dict[str, object]]] = []

    def fake_run_post_flux_kubectl(cmd, **kwargs):
        _ = kwargs
        if cmd[:2] == ["kubectl", "apply"]:
            docs = list(yaml.safe_load_all(Path(cmd[-1]).read_text(encoding="utf-8")))
            applied_docs.append(docs)

    monkeypatch.setattr(cli_module, "_run_post_flux_kubectl", fake_run_post_flux_kubectl)

    cli_module._apply_post_flux_manifest(manifest_path, env={})

    assert applied_docs == [[configmap]]


