    onboarding = payload["deploy"]["targets"][0]["soperator_onboarding"]
    onboarding["accepted"] = True
    onboarding["state"] = "existing-soperator-supported"
    onboarding["actions"] = [
        "approve-external-soperator-upgrade",
        "upgrade-external-node-template",
    ]
