def test_prune_redundant_app_chart_default_values_skips_chart_lookup_without_scalar_values(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    payload = {
        "apps": {
            "charts": [
                {
                    "id": "demo-app",
                    "instance_id": "demo-empty",
                    "enabled": True,
                    "repo": "oci://example.com/charts/demo-app",
                    "version": "1.0.0",
                    "values": {},
                },
                {
                    "id": "demo-app",
                    "instance_id": "demo-nested",
                    "enabled": True,
                    "repo": "oci://example.com/charts/demo-app",
                    "version": "1.0.0",
                    "values": {"nested": {}},
                },
                {
                    "id": "demo-app",
                    "instance_id": "demo-list",
                    "enabled": True,
                    "repo": "oci://example.com/charts/demo-app",
                    "version": "1.0.0",
                    "values": {"items": [{"name": "keep"}]},
                },
            ]
        }
    }
    app_entry = ComponentEntry(
        id="demo-app",
        scope="apps",
        config_path="apps.platform.demo-app",
        description="Demo app",
        chart_name="demo-app",
    )

    def _unexpected_chart_defaults(**_kwargs: object) -> dict[str, object]:
        pytest.fail("chart defaults should not be loaded when there are no scalar values")

    monkeypatch.setattr(cli_module, "_app_chart_default_values", _unexpected_chart_defaults)

    cli_module._prune_redundant_app_chart_default_values(
        payload=payload,
        app_entries=(app_entry,),
    )

    charts = payload["apps"]["charts"]
    assert charts[0]["values"] == {}
    assert charts[1]["values"] == {"nested": {}}
    assert charts[2]["values"] == {"items": [{"name": "keep"}]}


def test_create_prunes_redundant_live_chart_default_values_from_existing_config(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    deployments_root = tmp_path / "deployments"
    deployments_root.mkdir(parents=True, exist_ok=True)
    monkeypatch.setattr(
        "nebius_cxcli.cli.helm_chart_default_values",
        lambda **_kwargs: {
            "certgen": {
                "job": {
                    "securityContext": {
                        "allowPrivilegeEscalation": False,
                    }
                }
            }
        },
    )

    created = _create_non_interactive(
        deployments_root,
        "--infra",
        "mk8s",
        "--app",
        "gateway-helm",
    )
    assert created.exit_code == 0, created.output

    config_path = _project_config_path(deployments_root)
    payload = yaml.safe_load(config_path.read_text(encoding="utf-8"))
    charts = payload.get("apps", {}).get("charts", [])
    assert isinstance(charts, list)
    gateway_row = next(item for item in charts if item.get("id") == "gateway-helm")
    gateway_row["values"] = {
        "certgen": {
            "job": {
                "securityContext": {
                    "allowPrivilegeEscalation": False,
                }
            }
        }
    }
    config_path.write_text(yaml.safe_dump(payload, sort_keys=False), encoding="utf-8")

    refreshed = _create_non_interactive(
        deployments_root,
        "--force",
        "--infra",
        "mk8s",
        "--app",
        "gateway-helm",
    )
    assert refreshed.exit_code == 0, refreshed.output
    assert "Overwritten project:" in refreshed.output

    cleaned = yaml.safe_load(config_path.read_text(encoding="utf-8"))
    cleaned_gateway = next(
        item for item in cleaned["apps"]["charts"] if item.get("id") == "gateway-helm"
    )
    assert "securityContext" not in cleaned_gateway["values"]["certgen"]["job"]
    assert (
        cleaned_gateway["values"]["certgen"]["job"]["affinity"]
        == cleaned_gateway["values"]["deployment"]["pod"]["affinity"]
    )
    assert cleaned_gateway["values"]["config"]["envoyGateway"]["provider"]["type"] == "Kubernetes"


